C, G_, F_, Am, Dm, Em = (0, 'M'), (7, 'M'), (5, 'M'), (9, 'm'), (2, 'm'), (4, 'm')
def mix(*xs):
    out = np.zeros(max(len(x) for x in xs))
    for x in xs: out[:len(x)] += x
    return out
# new SFX for this episode
def s_clink29(): d = 0.4; n = int(SR * d); return mix(osc(2200, d)[:n] * env_ad(n, 0.001, 0.25) * 0.3, osc(3300, d)[:n] * env_ad(n, 0.001, 0.15) * 0.2)
def s_striker29(): return mix(s_bell(880, 1.6, 0.6), s_bell(1320, 1.2, 0.4), np.concatenate([np.zeros(int(SR * 0.05)), s_bell(1760, 1.0, 0.3)]))
def s_whirr29(d): n = int(SR * d); return mix(osc(220 + 30 * np.sin(2 * np.pi * 6 * T(d)), d, 'saw')[:n] * 0.05, bp(noise(d), 800, 3000)[:n] * 0.15) * env_ad(n, 0.1, d * 0.8)
def s_rev29(d=1.6): n = int(SR * d); return mix(osc(sweep(60, 260, d), d, 'saw')[:n] * 0.25, lp(noise(d), 500)[:n] * 0.4) * env_ad(n, 0.05, d * 0.9)
def s_pop29(): d = 0.9; n = int(SR * d); return mix(lp(noise(d), 2500)[:n] * env_ad(n, 0.001, 0.15) * 1.6, osc(sweep(400, 60, 0.4), 0.4)[:int(SR * 0.4)] * env_ad(int(SR * 0.4), 0.001, 0.3) * 0.8, s_clatter(0.9, 18, 3500) * 0.5)
def s_roll29(d): n = int(SR * d); return lp(noise(d), 160)[:n] * (0.6 + 0.4 * np.sin(2 * np.pi * 3 * T(d))[:n]) * env_ad(n, 0.3, d * 0.9) * 1.6
def s_buzz29(d): n = int(SR * d); return mix(osc(110, d, 'square')[:n] * 0.06, bp(noise(d), 2000, 6000)[:n] * (np.random.RandomState(29).rand(n) > 0.97) * 0.5) * env_ad(n, 0.05, d * 0.9)
def s_mega29(d=0.8): n = int(SR * d); return bp(osc(180 + 60 * np.sin(2 * np.pi * 9 * T(d)), d, 'saw'), 600, 2500)[:n] * env_ad(n, 0.02, d * 0.8) * 0.35
def s_firework29(): d = 1.6; w = int(SR * 0.7); return mix(np.concatenate([osc(sweep(1800, 600, 0.7), 0.7)[:w] * np.linspace(0.05, 0.2, w), lp(noise(0.9), 3000)[:int(SR * 0.9)] * env_ad(int(SR * 0.9), 0.001, 0.4) * 1.2]), np.zeros(int(SR * d)))
def s_crunch29(): d = 0.3; n = int(SR * d); return bp(noise(d), 1000, 5000)[:n] * env_ad(n, 0.001, 0.12) * 1.1
